-- NABUUMA RECIPE CONTROL v1.3 — security & production hardening
alter function public.is_member(uuid) set search_path = public;
alter function public.has_role(uuid, member_role[]) set search_path = public;
alter function public.create_business(text,text,text) set search_path = public;
alter function public.publish_recipe(uuid) set search_path = public;
alter function public.prevent_published_recipe_change() set search_path = public;
create or replace function public.enforce_same_business() returns trigger language plpgsql security definer set search_path=public as $$ declare parent_business uuid; child_business uuid; begin if tg_table_name='recipe_ingredients' then select business_id into parent_business from recipe_versions where id=new.recipe_version_id; select business_id into child_business from ingredients where id=new.ingredient_id; elsif tg_table_name='ingredient_prices' then select business_id into parent_business from ingredients where id=new.ingredient_id; if new.supplier_id is not null then select business_id into child_business from suppliers where id=new.supplier_id; end if; elsif tg_table_name='recipe_versions' then select business_id into parent_business from products where id=new.product_id; child_business := new.business_id; elsif tg_table_name in ('inventory_movements','waste_records') then select business_id into parent_business from ingredients where id=new.ingredient_id; child_business := new.business_id; elsif tg_table_name in ('training_assignments','assessments','certifications') then if tg_table_name='training_assignments' then select business_id into parent_business from staff_profiles where id=new.staff_id; select business_id into child_business from courses where id=new.course_id; elsif tg_table_name='assessments' then select business_id into parent_business from staff_profiles where id=new.staff_id; select business_id into child_business from courses where id=new.course_id; else select business_id into parent_business from staff_profiles where id=new.staff_id; select business_id into child_business from courses where id=new.course_id; end if; elsif tg_table_name in ('qc_checks','service_events') then select business_id into parent_business from products where id=new.product_id; child_business := new.business_id; else return new; end if; if parent_business is null or child_business is null or parent_business <> child_business then raise exception 'Cross-business reference rejected'; end if; return new; end $$;
drop trigger if exists recipe_ingredients_same_business on recipe_ingredients; create trigger recipe_ingredients_same_business before insert or update on recipe_ingredients for each row execute function public.enforce_same_business();
drop trigger if exists ingredient_prices_same_business on ingredient_prices; create trigger ingredient_prices_same_business before insert or update on ingredient_prices for each row execute function public.enforce_same_business();
drop trigger if exists recipe_versions_same_business on recipe_versions; create trigger recipe_versions_same_business before insert or update on recipe_versions for each row execute function public.enforce_same_business();
drop trigger if exists inventory_same_business on inventory_movements; create trigger inventory_same_business before insert or update on inventory_movements for each row execute function public.enforce_same_business();
drop trigger if exists waste_same_business on waste_records; create trigger waste_same_business before insert or update on waste_records for each row execute function public.enforce_same_business();
drop trigger if exists training_same_business on training_assignments; create trigger training_same_business before insert or update on training_assignments for each row execute function public.enforce_same_business();
drop trigger if exists assessment_same_business on assessments; create trigger assessment_same_business before insert or update on assessments for each row execute function public.enforce_same_business();
drop trigger if exists certification_same_business on certifications; create trigger certification_same_business before insert or update on certifications for each row execute function public.enforce_same_business();
drop trigger if exists qc_same_business on qc_checks; create trigger qc_same_business before insert or update on qc_checks for each row execute function public.enforce_same_business();
drop trigger if exists service_same_business on service_events; create trigger service_same_business before insert or update on service_events for each row execute function public.enforce_same_business();
create or replace function public.enforce_price_supplier_business() returns trigger language plpgsql security definer set search_path=public as $$ declare ib uuid; sb uuid; begin select business_id into ib from ingredients where id=new.ingredient_id; if new.supplier_id is not null then select business_id into sb from suppliers where id=new.supplier_id; end if; if ib is null or ib <> new.business_id or (new.supplier_id is not null and sb <> new.business_id) then raise exception 'Cross-business price reference rejected'; end if; return new; end $$;
drop trigger if exists ingredient_prices_same_business on ingredient_prices; create trigger ingredient_prices_same_business before insert or update on ingredient_prices for each row execute function public.enforce_price_supplier_business();
create or replace function public.prevent_published_recipe_change() returns trigger language plpgsql set search_path=public as $$ begin if old.status='published' then raise exception 'Published recipe versions are immutable'; end if; if tg_op='UPDATE' and old.status='draft' and new.status='archived' then return new; end if; if tg_op='UPDATE' and old.status='draft' and new.status='published' then raise exception 'Use publish_recipe() to publish recipes'; end if; return new; end $$;
drop policy if exists inventory_update on inventory_movements; drop policy if exists inventory_delete on inventory_movements; create policy inventory_no_delete on inventory_movements for delete using(false); create policy inventory_insert_strict on inventory_movements for insert with check(is_member(business_id) and has_role(business_id,ARRAY['owner','manager','staff']::member_role[]) and (movement_type <> 'adjustment' or has_role(business_id,ARRAY['owner','manager']::member_role[])));
drop policy if exists audit_write on audit_logs; create policy audit_write on audit_logs for insert with check(is_member(business_id) and user_id=auth.uid()); create policy audit_no_update on audit_logs for update using(false); create policy audit_no_delete on audit_logs for delete using(false);
drop policy if exists members_manage on business_members; create policy members_owner_manage on business_members for all using(has_role(business_id,ARRAY['owner']::member_role[])) with check(has_role(business_id,ARRAY['owner']::member_role[]));
create or replace function public.protect_last_owner() returns trigger language plpgsql security definer set search_path=public as $$ declare owners int; begin if tg_op='DELETE' or (tg_op='UPDATE' and new.role <> 'owner') then select count(*) into owners from business_members where business_id=old.business_id and role='owner' and id<>old.id; if owners=0 then raise exception 'A business must retain at least one owner'; end if; end if; return coalesce(new,old); end $$;
drop trigger if exists protect_last_owner on business_members; create trigger protect_last_owner before update or delete on business_members for each row execute function public.protect_last_owner();
create or replace function public.protect_system_columns() returns trigger language plpgsql as $$ begin new.id := old.id; new.business_id := old.business_id; new.created_at := old.created_at; return new; end $$;
drop trigger if exists protect_products_system on products; create trigger protect_products_system before update on products for each row execute function protect_system_columns(); drop trigger if exists protect_ingredients_system on ingredients; create trigger protect_ingredients_system before update on ingredients for each row execute function protect_system_columns();
revoke all on function public.create_business(text,text,text) from anon; grant execute on function public.create_business(text,text,text) to authenticated; revoke all on function public.publish_recipe(uuid) from anon; grant execute on function public.publish_recipe(uuid) to authenticated;
create index if not exists idx_prices_ingredient_effective on ingredient_prices(ingredient_id,effective_from desc); create index if not exists idx_service_business_time on service_events(business_id,served_at desc); create index if not exists idx_audit_business_time on audit_logs(business_id,created_at desc); create index if not exists idx_training_staff on training_assignments(business_id,staff_id); create index if not exists idx_qc_product_time on qc_checks(business_id,product_id,created_at desc);